export function shortcutContext(e,{modal=false,operation=false}={}){if(e.target?.isContentEditable||/INPUT|TEXTAREA|SELECT|SP-TEXTFIELD|SP-NUMBER-FIELD|SP-PICKER|SP-SLIDER|SP-CHECKBOX|SP-SWITCH/.test(e.target?.tagName))return 'TEXT_EDITING';if(modal)return 'MODAL';return operation?'TOOL_OPERATION':'DOCUMENT_EDITING';}
export function routeShortcut(e,{modal,operation,undo,redo,cancel,documentKey}){const context=shortcutContext(e,{modal,operation}),key=e.key.toLowerCase(),cmd=e.ctrlKey||e.metaKey;if(context==='TEXT_EDITING')return false;if(key==='escape'&&cancel?.(e)){e.preventDefault();return true;}if(context==='MODAL')return false;if(cmd&&(key==='z'||key==='y')){e.preventDefault();(key==='y'||e.shiftKey?redo:undo)();return true;}documentKey(e);return true;}
